/**
 * fix (2026-04-27): コミュニティ新規作成 ページ版 (ルート: /community/create)
 *
 * 経緯: SP では MatDialog 経由のモーダルが「クリックできない/反応が悪い」報告あり。
 * 構造的にモーダル z-index 戦争を回避するため、ルート遷移方式に移行。
 *
 * 設計:
 *  - 既存 CommunityCreateComponent (MatDialog 専用) はそのまま保持 (PC では引き続き利用可)
 *  - 当ファイルはページ版エントリ。同じフォーム UI を再利用するため、ロジックを再実装
 *  - 戻るボタン: ブラウザ戻る → /community へ
 *  - 作成成功: /community/:id へ遷移
 */
import { Component, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { MatIconModule } from '@angular/material/icon';
import { CommunityService } from '../../services/community.service';
import { ImageUploadComponent } from '../../../../shared/components/image-upload/image-upload.component';
import { NotificationService } from '../../../../shared/services/notification.service';

@Component({
  selector: 'app-community-create-page',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, ImageUploadComponent],
  templateUrl: './community-create-page.component.html',
  styleUrls: ['./community-create-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CommunityCreatePageComponent {
  imageUrl = '';
  title = '';
  description = '';
  tagsText = '';
  imageFile: File | null = null;

  constructor(
    private router: Router,
    private location: Location,
    private communityService: CommunityService,
    private notification: NotificationService,
  ) {}

  get imagePreviewUrl(): string | null {
    return this.imageUrl.trim() || null;
  }

  onImageSelected(event: { file: File; previewUrl: string }): void {
    this.imageFile = event.file;
  }

  onImageRemoved(): void {
    this.imageFile = null;
  }

  onBack(): void {
    /* ブラウザ戻る (履歴があれば) → なければ /community へ fallback */
    if (window.history.length > 1) {
      this.location.back();
    } else {
      this.router.navigate(['/community']);
    }
  }

  onCancel(): void {
    this.onBack();
  }

  onCreate(): void {
    if (!this.title.trim()) return;
    const tags = this.tagsText
      .split(',')
      .map(t => t.trim())
      .filter(t => t.length > 0);

    this.communityService
      .createCommunity({
        title: this.title.trim(),
        description: this.description.trim(),
        imageUrl: this.imageUrl.trim() || undefined,
        tags,
      })
      .subscribe(community => {
        this.notification.success('コミュニティを作成しました');
        this.router.navigate(['/community', community.id]);
      });
  }
}
